/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Types: VideoPreviewCardProps
 *   Functions: VideoPreviewCard
 * Internal
 *   Functions: UnavailablePreview, UnavailableOptions
 *   Constants: CardVideoPreview, VideoFrameOptions
 * @end-catalog */

import { lazy, Suspense, useCallback, useEffect, useId, useRef, useState, useSyncExternalStore, type ComponentType, type CSSProperties } from 'react';
import { MoreHorizontal, Pause, Play, VolumeX } from 'lucide-react';

import { contentByline, type AudioTrackSummary } from '../../api/contentSchemas';
import { Artwork } from '../../components/Artwork';
import { Icon } from '../../components/Icon';
import type { CardVideoPreviewProps } from '../../components/CardVideoPreview';
import { formatLocalizedMessage, useLocalization } from '../../localization/LocalizationProvider';
import { playerStore, usePlayingTrackId } from '../../player';
import { useVideoCardPreview } from './useVideoCardPreview';
import { videoTextFor } from './videoText';
import { VideoCardSave } from './VideoCardSave';
import type { VideoFrameOptionsProps } from './VideoFrameOptions';
import styles from './VideoPreviewCard.module.css';

/** A stale preview chunk releases pending intent while the artwork and real playback stay usable. */
const UnavailablePreview = ({ onStop }: CardVideoPreviewProps) => {
  useEffect(onStop, [onStop]);
  return null;
};
const CardVideoPreview = lazy(() => import('../../components/CardVideoPreview').catch(() => ({ default: UnavailablePreview })));

/** A missing optional framing chunk closes its disclosure without affecting the content or player. */
const UnavailableOptions = ({ onClose }: VideoFrameOptionsProps) => {
  useEffect(() => onClose(), [onClose]);
  return null;
};
const VideoFrameOptions = lazy<ComponentType<VideoFrameOptionsProps>>(() => import('./VideoFrameOptions').catch(() => ({ default: UnavailableOptions })));

export interface VideoPreviewCardProps {
  item: AudioTrackSummary;
  viewerId?: string | null;
  saved: boolean | null;
  onPlay: (track: AudioTrackSummary) => void;
}

/** Presents one real Video as an immersive card, with independent playback, preview and Save actions. */
export const VideoPreviewCard = ({ item, viewerId, saved, onPlay }: VideoPreviewCardProps) => {
  const { t, locale } = useLocalization();
  const text = videoTextFor(locale, formatLocalizedMessage);
  const title = item.title.trim() || t('content.title.untitled_track');
  const byline = contentByline(item);
  const playing = usePlayingTrackId() === item.id;
  const roomActive = useSyncExternalStore(playerStore.subscribe, playerStore.isRoomPlaybackActive, () => false);
  const preview = useVideoCardPreview(!playing && item.mediaType === 'video' ? item.streamUrl : null);
  const audible = preview.active && !preview.actualMuted;
  const [ready, setReady] = useState(false);
  const [optionsOpen, setOptionsOpen] = useState(false);
  const [fit, setFit] = useState<'cover' | 'contain'>('cover');
  const [position, setPosition] = useState(50);
  const optionsId = useId();
  const titleId = useId();
  const trigger = useRef<HTMLButtonElement>(null);
  const markReady = useCallback(() => setReady(true), []);
  const markLoading = useCallback(() => setReady(false), []);
  const stop = useCallback(() => { setReady(false); preview.stop(); }, [preview.stop]);

  useEffect(() => { if (!preview.active) setReady(false); }, [preview.active]);
  const closeOptions = useCallback((restoreFocus = true) => {
    setOptionsOpen(false);
    if (restoreFocus) trigger.current?.focus();
  }, []);
  const frameStyle = { '--video-fit': fit, '--video-position': `${position}%` } as CSSProperties;
  const metadata = [item.albumTitle, byline, item.duration].filter(Boolean).join(' · ');
  // The image and transport control share the same standalone playback and preview cleanup.
  const togglePlayback = () => {
    stop();
    if (playing) playerStore.pause();
    else onPlay(item);
  };

  return (
    <article aria-labelledby={titleId} className={styles.card} data-video-preview-card={item.id}
      onKeyDown={(event) => { if (optionsOpen && event.key === 'Escape') { event.preventDefault(); closeOptions(); } }} ref={preview.cardRef}>
      <div className={styles.frame} data-video-frame="portrait" style={frameStyle}>
        <Artwork alt="" className={styles.background} kind="audioTrack" sizes="(max-width: 600px) 100vw, 32rem" src={item.artworkUrl} />
        {preview.active && <Suspense fallback={null}>
          <CardVideoPreview className={styles.preview} intent={preview.intent} mediaTrackId={item.id} muted={preview.muted}
            onLoading={markLoading} onMuted={preview.reportMuted} onReady={markReady} onStop={stop} streamUrl={item.streamUrl} />
        </Suspense>}
        <div aria-hidden="true" className={styles.shade} />
        <header className={styles.heading}>
          <Artwork alt="" className={styles.cover} kind="audioTrack" sizes="5rem" src={item.artworkUrl} />
          <div className={styles.identity}>
            <p className={styles.kind}>{t('common.label.video')}</p>
            <h2 className={styles.title} id={titleId} title={title}>{title}</h2>
            {byline && <p className={styles.byline} title={byline}>{byline}</p>}
          </div>
        </header>
        <div className={styles.description}>
          {item.albumTitle && <p title={item.albumTitle}>{item.albumTitle}</p>}
          {metadata && <span title={metadata}>{metadata}</span>}
        </div>
        <button aria-label={text(playing ? 'videos.card.pause' : 'videos.card.play', { title })}
          data-video-open="" onClick={togglePlayback} title={title} type="button"
          style={{ position: 'absolute', inset: 0, zIndex: 3, background: 'transparent', border: 0,
            padding: 0, borderRadius: 'inherit', cursor: 'pointer', outlineOffset: '-4px' }} />
        <div className={styles.actions} style={{ pointerEvents: 'none' }}>
          <button aria-label={text(audible ? 'videos.preview.stop' : 'videos.preview.action', { title })}
            aria-pressed={audible} className={styles.previewButton} data-preview-trigger=""
            disabled={playing || roomActive} onClick={preview.toggle}
            style={{ pointerEvents: 'auto' }} title={roomActive ? t('content.album.play_room_active', { title }) : undefined} type="button">
            {audible ? <Icon name="volume" size={17} /> : <VolumeX aria-hidden="true" size={17} />}
            <span>{text(ready && audible ? 'videos.preview.active'
              : ready && preview.active && !preview.muted ? 'videos.preview.enable_sound' : 'videos.preview.label')}</span>
          </button>
          <span className={styles.spacer} />
          <button aria-controls={optionsOpen ? optionsId : undefined} aria-expanded={optionsOpen}
            aria-haspopup="dialog" aria-label={text('videos.card.options', { title })}
            className={styles.iconButton} onClick={() => { stop(); setOptionsOpen((open) => !open); }} ref={trigger}
            style={{ pointerEvents: 'auto' }} type="button">
            <MoreHorizontal aria-hidden="true" size={24} />
          </button>
          <span className={styles.saveSlot} style={{ pointerEvents: 'auto' }}><VideoCardSave compact saved={saved} target={{ contentType: 'audioTrack', contentId: item.id }} viewerId={viewerId} /></span>
          <button aria-label={playing ? t('content.pause.label', { title }) : byline
            ? t('content.play.byline_label', { title, byline }) : t('content.play.label', { title })}
            className={`${styles.play} ${playing ? styles.playing : ''}`} onClick={togglePlayback}
            style={{ pointerEvents: 'auto' }} type="button">
            {playing ? <Pause aria-hidden="true" fill="currentColor" size={24} /> : <Play aria-hidden="true" fill="currentColor" size={24} />}
          </button>
        </div>
        {optionsOpen && <Suspense fallback={<div className={styles.options} role="status">{t('home.loading.title')}</div>}>
          <VideoFrameOptions fit={fit} id={optionsId} onClose={closeOptions} onFit={setFit} onPosition={setPosition}
            position={position} title={title} triggerRef={trigger} />
        </Suspense>}
      </div>
    </article>
  );
};
